  ('Rubidoux Drive-In Theatre', '3770 Opal St', 'Riverside', 'CA', 'California', 37.28025, -121.84033, 'This retro drive-in movie theater screens the latest releases & pipes sound into cars via FM radio.', 'https://www.westwinddi.com/locations/capitol', 'isobel78@gmail.com'),
  ('Magic City Drive In', '5602 S Cleveland Massillon Rd', 'Barberton', 'OH', 'Ohio', 40.9862, -81.63513, '1950s-era drive-in movie theater with 2 digital screens & a concession stand for snacks.', 'https://www.magiccitydrive-in.com/', 'rh72dgTkWiR6dTeHw9byv2rzqPC2'),
